static void dynamic(API&n,API&g){phase="dynamic free/chunk/state";sym<decltype(&ggml_set_abort_callback)>(g.h,"ggml_set_abort_callback")(diagnostic_abort);diagnostic_api=&g;struct Live{std::array<uint64_t,2>a,b;size_t bytes;};std::vector<uint64_t>x(65536),y(65536);for(size_t align:{size_t(16),size_t(64),size_t(128)})for(size_t cap:{size_t(256),size_t(1024),size_t(4096)}){void*a=n.dyn_new(align,cap),*b=g.dyn_new(align,cap);diagnostic_dyn=b;std::vector<Live>live;uint32_t seed=1729;for(int step=0;step<1200;++step){seed=seed*1664525+1013904223;bool allocate=live.empty()||(live.size()<72&&(seed&3)!=0);if(allocate){size_t bytes=(seed>>8)%513;Live v{};v.bytes=bytes;n.dyn_alloc(a,bytes,v.a.data());std::snprintf(current_operation,sizeof current_operation,"align=%zu cap=%zu step=%d alloc=%zu",align,cap,step,bytes);g.dyn_alloc(b,bytes,v.b.data());req(v.a==v.b,"exact chunk/offset selection");live.push_back(v);}else{size_t i=(seed>>8)%live.size();auto v=live[i];n.dyn_release(a,(int)v.a[0],v.a[1],v.bytes);std::snprintf(current_operation,sizeof current_operation,"align=%zu cap=%zu step=%d free={chunk=%llu off=%llu bytes=%zu}",align,cap,step,(unsigned long long)v.b[0],(unsigned long long)v.b[1],v.bytes);g.dyn_release(b,(int)v.b[0],v.b[1],v.bytes);live.erase(live.begin()+i);}auto na=n.dyn_snapshot(a,x.data(),x.size()),nb=g.dyn_snapshot(b,y.data(),y.size());req(na==nb&&std::memcmp(x.data(),y.data(),na*8)==0,"exact free lists/high-water/chunks");++dynamic_ops;}for(auto&v:live){n.dyn_release(a,(int)v.a[0],v.a[1],v.bytes);g.dyn_release(b,(int)v.b[0],v.b[1],v.bytes);}n.dyn_reset(a);g.dyn_reset(b);auto na=n.dyn_snapshot(a,x.data(),x.size()),nb=g.dyn_snapshot(b,y.data(),y.size());req(na==nb&&std::memcmp(x.data(),y.data(),na*8)==0,"reset empties all chunks");n.dyn_free(a);g.dyn_free(b);}}
