struct Mock{API*a;ggml_backend_buffer_type kind{};size_t align,maxsize,hard_limit=SIZE_MAX;int shift=0,live=0,next=0;std::vector<std::string>events;Mock(API&api,size_t al=64,size_t max=1024):a(&api),align(al),maxsize(max){kind.context=this;kind.iface.get_name=[](ggml_backend_buffer_type_t){return "test-buffer";};kind.iface.get_alignment=[](ggml_backend_buffer_type_t t){return ((Mock*)t->context)->align;};kind.iface.get_max_size=[](ggml_backend_buffer_type_t t){return ((Mock*)t->context)->maxsize;};kind.iface.get_alloc_size=[](ggml_backend_buffer_type_t t,const ggml_tensor*x){return ((Mock*)t->context)->a->ggml_nbytes(x);};kind.iface.is_host=[](ggml_backend_buffer_type_t){return true;};kind.iface.alloc_buffer=[](ggml_backend_buffer_type_t t,size_t n)->ggml_backend_buffer_t{auto*m=(Mock*)t->context;m->events.push_back("alloc:"+std::to_string(n)+(n>m->hard_limit?":fail":":ok"));if(n>m->hard_limit)return nullptr;unsigned char*raw=nullptr;if(posix_memalign((void**)&raw,m->align,n+m->align+64)!=0)return nullptr;std::memset(raw,0x7b,n+m->align+64);auto*data=new Buffer{m,raw,raw+m->shift,n,m->next++};ggml_backend_buffer_i iface{};iface.free_buffer=[](ggml_backend_buffer_t b){auto*d=(Buffer*)b->context;d->owner->events.push_back("free:"+std::to_string(d->id));--d->owner->live;std::free(d->raw);delete d;};iface.get_base=[](ggml_backend_buffer_t b)->void*{return ((Buffer*)b->context)->base;};iface.init_tensor=[](ggml_backend_buffer_t b,ggml_tensor*x){auto*d=(Buffer*)b->context;d->owner->events.push_back("init:"+std::to_string(d->id)+":"+x->name+":"+std::to_string((uintptr_t)x->data-(uintptr_t)d->base));return GGML_STATUS_SUCCESS;};iface.reset=[](ggml_backend_buffer_t b){auto*d=(Buffer*)b->context;d->owner->events.push_back("reset:"+std::to_string(d->id));};++m->live;return m->a->ggml_backend_buffer_init(t,iface,data,n);};}};
static void events(Mock&a,Mock&b){if(a.events!=b.events){for(size_t i=0;i<a.events.size()||i<b.events.size();++i){auto x=i<a.events.size()?a.events[i]:"<end>",y=i<b.events.size()?b.events[i]:"<end>";if(x!=y){std::fprintf(stderr,"EVENT %zu native=%s goose=%s\n",i,x.c_str(),y.c_str());break;}}}req(a.events==b.events,"exact backend alloc/free/reset/init order");events_checked+=a.events.size();req(a.live==b.live,"backend ownership count");}
