static void tensor_compare(Context&n,Context&g){auto*a=n.a.ggml_get_first_tensor(n.c),*b=g.a.ggml_get_first_tensor(g.c);while(a&&b){req(a->type==b->type&&a->op==b->op&&a->flags==b->flags,"tensor metadata");req(bool(a->buffer)==bool(b->buffer)&&bool(a->data)==bool(b->data),"tensor allocation presence");if(a->buffer&&b->buffer){auto*x=(Buffer*)a->buffer->context,*y=(Buffer*)b->buffer->context;req(x->id==y->id&&(uintptr_t)a->data-(uintptr_t)x->base==(uintptr_t)b->data-(uintptr_t)y->base,"tensor backend/chunk/data offset");req(a->buffer->usage==b->buffer->usage,"buffer usage");}a=n.a.ggml_get_next_tensor(n.c,a);b=g.a.ggml_get_next_tensor(g.c,b);}req(!a&&!b,"tensor population");}
