static Built make(Context&x,int length,int64_t size,bool views){auto&a=x.a;auto*root=x.t(size,"input"),*bias=x.t(size,"bias");a.ggml_set_input(root);a.ggml_set_input(bias);auto*out=root;for(int i=0;i<length;++i){out=i%2?a.ggml_mul(x.c,out,bias):a.ggml_add(x.c,out,bias);a.ggml_set_name(out,("node"+std::to_string(i)).c_str());if(views&&i%3==1){out=a.ggml_view_1d(x.c,out,size,0);a.ggml_set_name(out,("view"+std::to_string(i)).c_str());}}a.ggml_set_output(out);auto*g=a.ggml_new_graph_custom(x.c,256,false);a.ggml_build_forward_expand(g,out);return {g,root};}
static void graph_suite(API&n,API&g){phase="graph allocator/control/backend ownership";std::vector<uint64_t>aa(65536),bb(65536);for(bool multi:{false,true})for(bool views:{false,true})for(int length:{1,4,17}){Context x(n),y(g);Mock na(n,64,512),ga(g,64,512),nb(n,128,1024),gb(g,128,1024);ggml_backend_buffer_type_t nt[]={&na.kind,&nb.kind,&na.kind},gt[]={&ga.kind,&gb.kind,&ga.kind};int nbuf=multi?3:1;auto a=n.ggml_gallocr_new_n(nt,nbuf),b=g.ggml_gallocr_new_n(gt,nbuf);size_t limits[]={2048,4096,1024};n.ggml_gallocr_set_buffer_growth_limits(a,limits);g.ggml_gallocr_set_buffer_growth_limits(b,limits);auto p=make(x,length,16,views),q=make(y,length,16,views);std::vector<int>ids(p.graph->n_nodes);for(size_t i=0;i<ids.size();++i)ids[i]=multi?(int)(i%3):0;std::vector<int>leafids(p.graph->n_leafs);for(size_t i=0;i<leafids.size();++i)leafids[i]=multi?(int)(i%3):0;size_t ns[3]={},gs[3]={};n.ggml_gallocr_reserve_n_size(a,p.graph,ids.data(),leafids.data(),ns);g.ggml_gallocr_reserve_n_size(b,q.graph,ids.data(),leafids.data(),gs);req(std::memcmp(ns,gs,nbuf*sizeof(size_t))==0,"measurement/reservation sizes");req(n.ggml_gallocr_reserve_n(a,p.graph,ids.data(),leafids.data())==g.ggml_gallocr_reserve_n(b,q.graph,ids.data(),leafids.data()),"reserve status");auto as=n.graph_snapshot(a,p.graph,aa.data(),aa.size()),bs=g.graph_snapshot(b,q.graph,bb.data(),bb.size());req(as==bs&&std::memcmp(aa.data(),bb.data(),as*8)==0,"reservation lifetime/reuse/free-list state");req(n.ggml_gallocr_alloc_graph(a,p.graph)==g.ggml_gallocr_alloc_graph(b,q.graph),"graph allocation status");tensor_compare(x,y);events(na,ga);events(nb,gb);req(n.ggml_gallocr_alloc_graph(a,p.graph)==g.ggml_gallocr_alloc_graph(b,q.graph),"same graph buffer reuse");for(int i=0;i<nbuf;++i)req(n.ggml_gallocr_get_buffer_size(a,i)==g.ggml_gallocr_get_buffer_size(b,i),"shared buffers counted once");n.ggml_gallocr_set_buffer_growth_limits(a,nullptr);g.ggml_gallocr_set_buffer_growth_limits(b,nullptr);n.ggml_gallocr_free(a);g.ggml_gallocr_free(b);events(na,ga);events(nb,gb);req(na.live==0&&nb.live==0,"owned buffers freed once");++graphs_checked;}
phase="automatic growth and reserve failure";for(size_t hard:{size_t(300),size_t(0),SIZE_MAX}){Context x(n),y(g);Mock na(n,64,512),ga(g,64,512);na.hard_limit=ga.hard_limit=hard;auto a=n.ggml_gallocr_new(&na.kind),b=g.ggml_gallocr_new(&ga.kind);size_t limits=1024;n.ggml_gallocr_set_buffer_growth_limits(a,&limits);g.ggml_gallocr_set_buffer_growth_limits(b,&limits);auto p=make(x,4,16,false),q=make(y,4,16,false);bool nr=n.ggml_gallocr_alloc_graph(a,p.graph),gr=g.ggml_gallocr_alloc_graph(b,q.graph);req(nr==gr,"automatic reserve and allocation failure");events(na,ga);if(nr)tensor_compare(x,y);n.ggml_gallocr_free(a);g.ggml_gallocr_free(b);events(na,ga);req(na.live==0,"failed/grown backend cleanup");}}
